-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warlock.dps.Name"] = "Tutti gli alberi"
L["rm.era.warlock.dps.Description"] = "Livelli 1–60, ogni albero dei talenti, anche sui reami Hardcore e Self-Found; costruita a partire da Wowhead, Icy Veins, Warcraft Tavern e simulatore. Si ferma mentre lanci o incanali e, quando giochi da solo, non attacca mai per primo un mostro che qualcun altro sta combattendo. Prima la Trance d'Ombra di Notte Fonda; Combustione dell'Ombra e Dolore Ustionante per finire un bersaglio in gruppo; un bersaglio in punto di morte quando giochi da solo riceve Risucchio d'Anima (per un frammento, o con Risucchio d'Anima Migliorato), Combustione dell'Ombra o Conflagrazione, poi la bacchetta, mai nuovi DoT. In movimento solo incantesimi istantanei. Contro tre o più nemici: Fuoco Infernale quando ti sono addosso e hai metà della salute, altrimenti Pioggia di Fuoco. Una maledizione: in incursione Maledizione dell'Ombra o degli Elementi quando nessuno l'ha messa, Rovina nei combattimenti lunghi contro élite, altrimenti Agonia. Immolazione quando conviene (Distruzione, incursioni, o con il 40% di mana), Corruzione, Aspirazione della Vita (in incursione solo con Vulnerabilità all'Ombra). Da solo: Patto Oscuro, Conversione Vitale quando sei in salute, Risucchio di Vita quando sei ferito, la bacchetta. Altrimenti Dardo d'Ombra. Promemoria: Armatura Demoniaca o Pelle Demoniaca, il tuo famiglio (Ombra del Vuoto da solo, Imp in gruppo, Succube per Sacrificio Demoniaco), Vildominio, Sacrificio Demoniaco, Amplificazione Maledizione, Sacrificio dell'Ombra del Vuoto e una Pietra della Salute quando sei in difficoltà, Trasfusione Vitale. L'assegnazione delle maledizioni, Maledizione dell'Avventatezza su un mostro in fuga, Paura, Esilio, Pietre dell'Anima e la creazione delle Pietre della Salute restano a te."
L["rm.era.warlock.dps.icyveins.Name"] = "Maledizione e Corruzione in incursione (Icy Veins)"
L["rm.era.warlock.dps.icyveins.Description"] = "La lista di Icy Veins per i reami con il limite di 16 penalità, un'alternativa alla rotazione integrata consigliata dello Stregone, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. In incursione solo la tua maledizione e Corruzione, poi Dardo d'Ombra, senza Immolazione né Aspirazione della Vita. Livellamento e spedizioni si giocano come nella rotazione integrata consigliata."
L["rm.era.warlock.dps.warcrafttavern.Name"] = "Risucchio difensivo (Warcraft Tavern)"
L["rm.era.warlock.dps.warcrafttavern.Description"] = "Lo stile di livellamento di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata dello Stregone, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. L'Imp, poi la Succube dal livello 20. Immolazione, Aspirazione della Vita e Corruzione, poi da solo Risucchio di Vita come riempitivo una volta appreso il suo quarto grado (prima la bacchetta), Conversione Vitale ogni volta che la tua salute è quasi piena e Patto Oscuro prima che il mana del famiglio sia pieno. In incursione tutti i DoT che i posti consentono, poi Dardo d'Ombra. Stesse mosse per finire, maledizione e promemoria di sicurezza della rotazione integrata consigliata; impaurire un secondo mostro resta a te."
L["rm.forever.warlock.dps.Name"] = "Tutti gli alberi"
L["rm.forever.warlock.dps.Description"] = "Ogni albero dei talenti dello Stregone dal livello 1 al 60, unendo Icy Veins, Wowhead e Method; i passaggi di un albero compaiono una volta che conosci i suoi incantesimi da talento. Ingaggia con Immolazione e Flagello dell'Agonia (Distruzione prelancia Dardo d'Ombra), sfrutta gli effetti di Calar della Notte e Decimazione, mantiene Marchio Demoniaco con Dolore Bruciante. In movimento lancia solo incantesimi istantanei. Contro i gruppi: Fuoco Infernale in gruppo, Pioggia di Fuoco, Corruzione e Agonia. Poi Flagello della Rovina su élite e boss oppure Flagello dell'Agonia, Maledizione degli Elementi in gruppo e sulle élite, Immolazione, Corruzione, Sifone di Vita, Conflagrazione e Combustione dell'Ombra; da solo riempie con Tormento, Risucchio di Vita (con un talento di risucchio) o la bacchetta; altrimenti Incenerimento o Dardo d'Ombra. Promemoria: armatura, un demone (Succube, altrimenti Ombra del Vuoto, altrimenti Imp), Dominazione Vile, Sacrificio Demoniaco con Patto Demoniaco, Legame d'Anima, pietre per armi, Amplifica Maledizione e Flagello dello Scompiglio per un secondo nemico. Restano a te: mandare all'attacco il famiglio, le altre maledizioni, Paura, le Pietre della Salute e gli altri bersagli. Su Forever salute e mana sono nascosti agli addon, quindi la finestra di esecuzione (Risucchio d'Anima, Combustione dell'Ombra come colpo di grazia), Conversione Vitale, Trasfusione Vitale e i risucchi quando sei ferito sono una tua scelta."
L["rm.forever.warlock.dps.icyveins.Name"] = "Tutti gli alberi (Icy Veins)"
L["rm.forever.warlock.dps.icyveins.Description"] = "Il livellamento dello Stregone di Icy Veins: la bacchetta è il riempitivo da solo, l'Ombra del Vuoto è il demone predefinito, Afflizione e Distruzione sacrificano il loro demone e giocano senza (dal 41 e dal 55), Demonologia mantiene Marchio Demoniaco e usa Immolazione solo come riempitivo, e Distruzione mette Flagello dello Scompiglio sul nemico più resistente di un gruppo e usa Conflagrazione appena pronta una volta appreso Incenerimento. Sceglila al posto della rotazione integrata consigliata per lo Stregone se segui Icy Veins. Su Forever salute, mana e tempo alla morte sono nascosti agli addon, quindi Risucchio di Vita quando sei ferito, Conversione Vitale e quali bersagli vivranno abbastanza a lungo per i danni periodici sono una tua scelta. Un'alternativa alla rotazione integrata consigliata DPS dello Stregone, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.forever.warlock.dps.wowhead.Name"] = "Tutti gli alberi (Wowhead)"
L["rm.forever.warlock.dps.wowhead.Description"] = "Lo Stregone di livello 30 di Wowhead: Afflizione e Demonologia fanno \"drain-tanking\" con la Succube (Corruzione e Agonia, niente Immolazione, poi Risucchio di Vita per il resto del combattimento; su Forever salute e mana sono nascosti, quindi Conversione Vitale è una tua scelta), Demonologia mantiene Marchio Demoniaco e applica Agonia solo ai bersagli robusti, Distruzione mette Agonia, Corruzione e Immolazione su ogni mostro, usa Conflagrazione poco prima che Immolazione finisca, tiene Combustione dell'Ombra per il colpo di grazia e usa la bacchetta con l'Ombra del Vuoto. Amplifica Maledizione a ogni tempo di recupero; Maledizione degli Elementi e Flagello della Rovina solo su élite e boss; nessuna sezione per i gruppi di nemici. Le guide di Wowhead si fermano al livello 30. Un'alternativa alla rotazione integrata consigliata DPS dello Stregone, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.mop.warlock.affliction.Name"] = "Consigliata"
L["rm.mop.warlock.affliction.Description"] = "Consigliata per Afflizione dal livello 10 al 90 (scelta nella specializzazione Afflizione). Prelancia Tormento o Afflizione Instabile, apre contro un'élite appena ingaggiata con Consumo d'Anima e Scambio d'Anima, mantiene attivi Agonia, Corruzione e Afflizione Instabile (rinnovandoli in anticipo mentre è attiva Anima Oscura: Miseria), lancia Tormento ogni volta che sta per finire e hai due frammenti d'anima (o durante Anima Oscura), incanala Risucchio d'Anima per un frammento quando Tormento sta per finire e non ne hai, Risucchio d'Anima sotto il 20%, altrimenti Stretta Malefica (Dardo d'Ombra prima del livello 42). Seme della Corruzione contro tre o più nemici (con Consumo d'Anima contro sei). In movimento: incantesimi istantanei e Vilfiamma. Promemoria: il tuo famiglio, Intento Oscuro, Maledizione degli Elementi in gruppo, Anima Oscura, Demone Guardiano o Infernale, Rito del Servizio o del Sacrificio, Conversione Vitale, abilità difensive. Lasciati a te: diffondere i DoT su altri bersagli e gli spostamenti con Scambio d'Anima tra di essi."
L["rm.mop.warlock.affliction.warcrafttavern.Name"] = "Accumulo per Tormento (Warcraft Tavern)"
L["rm.mop.warlock.affliction.warcrafttavern.Description"] = "Disattivata per impostazione predefinita. La gestione dei frammenti d'anima di Warcraft Tavern e Method: lo stesso mantenimento dei DoT della rotazione integrata Afflizione consigliata, ma Tormento viene conservato per quattro frammenti o per Anima Oscura: Miseria, e sotto il 20% Consumo d'Anima e Scambio d'Anima rinnovano ogni DoT ogni volta che hai un frammento. Per usarla attivala e disattiva la rotazione integrata Afflizione consigliata."
L["rm.mop.warlock.demonology.Name"] = "Consigliata"
L["rm.mop.warlock.demonology.Description"] = "Consigliata per Demonologia dal livello 10 al 90 (scelta nella specializzazione Demonologia). In forma da incantatore: Corruzione, Mano di Gul'dan in base alle cariche, una seconda Mano di Gul'dan prima di Metamorfosi quando un Ombrofuoco con un solo cumulo sta per scadere, Metamorfosi con Anima Oscura: Conoscenza (o con la furia demoniaca quasi piena), Fuoco dell'Anima a due cumuli di Nucleo Ardente o sotto il 25%, Fuoco Infernale contro quattro o più nemici, Dardo d'Ombra. Durante Metamorfosi: Rovina, Tocco del Caos per mantenere Corruzione, Fuoco dell'Anima con Nucleo Ardente, Rogo Rovente o Raggio del Vuoto sui gruppi di nemici, Tocco del Caos, e un segnale per uscirne quando Anima Oscura non è attiva e la furia demoniaca è a 300 o meno. Promemoria: Vilguardia (o Guardia dell'Ira), Intento Oscuro, Anima Oscura, Sciame di Imp, Rito del Servizio: Vilguardia, Demone Guardiano o Infernale, Conversione Vitale, Trasfusione Vitale da solo. Lasciati a te: Viltempesta (lancio automatico del famiglio) e Balzo Demoniaco."
L["rm.mop.warlock.demonology.guide.Name"] = "Accumulo di Nucleo Ardente (guide)"
L["rm.mop.warlock.demonology.guide.Description"] = "Disattivata per impostazione predefinita. Il consenso delle guide (Method, wowtbc.gg, Warcraft Tavern, Wowhead): la rotazione integrata Demonologia consigliata, tranne che in forma da incantatore Metamorfosi aspetta 900 di furia demoniaca o Anima Oscura e Fuoco dell'Anima viene lanciato solo a otto cumuli di Nucleo Ardente o sotto il 25%, così i cumuli vengono spesi in forma demoniaca. Per usarla attivala e disattiva la rotazione integrata Demonologia consigliata."
L["rm.mop.warlock.destruction.Name"] = "Consigliata"
L["rm.mop.warlock.destruction.Description"] = "Per Distruzione dal livello 10 al 90 (scelta nella specializzazione Distruzione). Prelancia Incenerimento, mantiene attiva Immolazione, non resta mai ferma su due cariche di Conflagrazione, spende le braci in Dardo del Caos (Combustione dell'Ombra sotto il 20%) a 3,5 braci o durante Anima Oscura: Instabilità, usa Ritorno di Fiamma su Incenerimento, e riempie con Incenerimento; un bersaglio in punto di morte riceve Combustione dell'Ombra. Contro tre o più nemici: Pioggia di Fuoco e Fuoco e Zolfo contro quattro, poi Immolazione, Conflagrazione e Incenerimento, e un segnale per disattivare Fuoco e Zolfo quando finisci le braci. In movimento: Combustione dell'Ombra, Conflagrazione, Vilfiamma. Promemoria: il tuo famiglio o Rito del Sacrificio, Fiamme di Xoroth, Intento Oscuro, Anima Oscura, Calamità contro due o più nemici (lanciala tu sul secondo bersaglio), Demone Guardiano o Infernale, Conversione delle Braci e abilità difensive."
L["rm.mop.warlock.unspecialized.Name"] = "Senza specializzazione"
L["rm.mop.warlock.unspecialized.Description"] = "Per uno Stregone senza specializzazione (livelli da 1 a 9, o più avanti prima di sceglierne una). Corruzione per ingaggiare e mantenuta attiva, Risucchio di Vita sotto metà della salute, Dardo d'Ombra. Promemoria: l'Ombra del Vuoto quando giochi da solo (l'Imp in gruppo), e una Pietra della Salute tra un ingaggio e l'altro."
L["rm.retail.warlock.affliction.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warlock.affliction.Description"] = "Consigliata per Afflizione in Midnight. In combattimento il gioco ora nasconde agli addon i tuoi danni periodici, i proc, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante, che mantiene Agonia e Corruzione, spende i frammenti su Afflizione Instabile e gestisce Rito del Sacrificio), e si ferma mentre lanci, incanali o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Evocazione: Lumenero in combattimento, un Vilsegugio tra un ingaggio e l'altro a meno che tu non abbia sacrificato il tuo demone, Ordine Demoniaco su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio), Patto Oscuro e Determinazione Assoluta ogni volta che sono pronti in combattimento (la salute è nascosta su Retail, quindi decidi tu quando usarli)."
L["rm.retail.warlock.affliction.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.warlock.affliction.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft (Mietitore d'Anime) legge i timer dei danni periodici, Notte Fonda e Frammento dell'Instabilità, che Midnight nasconde in combattimento. Tormento prima dell'ingaggio; Seme della Corruzione contro tre o più nemici ingaggiati senza la tua Corruzione; Tormento; Agonia e Corruzione o Avvizzimento sotto i 3 secondi; Raccolto Oscuro a due frammenti o meno; Afflizione Instabile a 5 frammenti; Stretta Malefica, altrimenti Dardo d'Ombra, con due cumuli di Notte Fonda; Afflizione Instabile con Frammento dell'Instabilità o a 4 frammenti; Risucchio d'Anima; Dardo d'Ombra. Promemoria: Evocazione: Lumenero quando Raccolto Oscuro è in recupero, Malevolenza, il tuo Vilsegugio e quelli comuni."
L["rm.retail.warlock.demonology.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warlock.demonology.Description"] = "Consigliata per Demonologia in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (Richiamo Inseguitore Maligno, Mano di Gul'dan, Dardo Demoniaco, Aspirazione di Potere e Tiranno), e si ferma mentre lanci, incanali o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Evocazione: Tiranno Demoniaco mentre sono presenti gli Inseguitori Maligni che hai richiamato negli ultimi 12 secondi, Rito del Servizio: Signore degli Imp, Rito del Servizio: Vildevastatore ed Evocazione: Demone Guardiano in combattimento, una Vilguardia tra un ingaggio e l'altro, Ordine Demoniaco, Patto Oscuro, Determinazione Assoluta."
L["rm.retail.warlock.demonology.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.warlock.demonology.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft (Demonista) legge Nucleo Demoniaco, il numero di imp e i timer dei tempi di recupero, che Midnight nasconde in combattimento. Aspirazione di Potere, Dardo Demoniaco e Dardo d'Ombra prima dell'ingaggio; poi Aspirazione di Potere con un Nucleo Demoniaco o nessuno, Rito del Servizio: Signore degli Imp, Rito del Servizio: Vildevastatore, Evocazione: Demone Guardiano, Richiamo Inseguitore Maligno, Evocazione: Tiranno Demoniaco a 5 frammenti, Implosione contro tre o più nemici ingaggiati, Sfacelo, Mano di Gul'dan a 3 frammenti o più, Dardo Infernale sotto 3, Dardo Demoniaco con Nucleo Demoniaco sotto 4, Dardo d'Ombra."
L["rm.retail.warlock.destruction.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warlock.destruction.Description"] = "Consigliata per Distruzione in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (Immolazione o Avvizzimento, Conflagrazione, Dardo del Caos, Pioggia di Fuoco, Fuoco dell'Anima, Malevolenza), e si ferma mentre lanci, incanali o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Evocazione: Infernale in combattimento, un Imp tra un ingaggio e l'altro a meno che tu non abbia sacrificato il tuo demone, Ordine Demoniaco, Patto Oscuro, Determinazione Assoluta. Calamità su un secondo bersaglio resta a te."
L["rm.retail.warlock.destruction.icyveins.Name"] = "Dardo del Caos prima del massimo, riferimento (Icy Veins)"
L["rm.retail.warlock.destruction.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Invocatore Infernale di Icy Veins, che spende i frammenti su Dardo del Caos prima che raggiungano il massimo e usa Combustione dell'Ombra e Canalizzazione Fuoco Demoniaco appena pronti. Pioggia di Fuoco contro tre o più nemici ingaggiati; Avvizzimento o Immolazione mantenuti attivi; Evocazione: Infernale; Malevolenza; Combustione dell'Ombra; Fuoco dell'Anima sotto 4 frammenti; Dardo del Caos a 4 o più; Cataclisma; Dardo Infernale sotto 4; Canalizzazione Fuoco Demoniaco; Conflagrazione; Incenerimento."
L["rm.retail.warlock.destruction.simc.Name"] = "Riferimento (SimulationCraft)"
L["rm.retail.warlock.destruction.simc.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di SimulationCraft legge Immolazione, Ritorno di Fiamma, le cariche e i timer dei tempi di recupero, che Midnight nasconde in combattimento. Fuoco dell'Anima e Incenerimento prima dell'ingaggio; contro tre o più nemici ingaggiati Pioggia di Fuoco a 3 frammenti e Cataclisma; poi Fuoco dell'Anima a 4 frammenti o meno, Dardo del Caos solo a 5, Conflagrazione a due cariche o sotto 4 frammenti senza Ritorno di Fiamma, Evocazione: Infernale, Malevolenza, Avvizzimento o Immolazione nell'ultimo 30% della durata, Sfacelo, Cataclisma, Dardo Infernale a 3 frammenti o meno, Incenerimento."
L["rm.retail.warlock.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.warlock.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale dello Stregone). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata dello Stregone condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.sod.warlock.fire.Name"] = "Fuoco (SoD)"
L["rm.sod.warlock.fire.Description"] = "Distruzione della Season of Discovery, scelta una volta incisi Dardo del Caos o Incenerimento; costruita a partire da simulatore Fase 6 e Wowhead. Combustione dell'Ombra e Dolore Ustionante per finire; incantesimi istantanei in movimento; l'effetto benefico di Incenerimento, Lago di Fuoco e Fuoco Infernale sui gruppi di nemici; una maledizione (Avventatezza in gruppo quando nessuno l'ha messa, Rovina nei combattimenti lunghi contro élite, altrimenti Agonia); Conflagrazione solo per mantenere Ritorno di Fiamma; Immolazione e l'effetto benefico di Incenerimento sempre attivi; sotto il 35% Fuoco dell'Anima con Decimazione invece di Dardo del Caos; proc di Fuoco dell'Anima!; Dardo del Caos; da solo Risucchio di Vita con Maestro dell'Incanalamento e Conversione Vitale; Incenerimento (Dardo d'Ombra prima di inciderlo). Promemoria: Armatura Vile, l'Imp, Amplificazione Maledizione e i promemoria di sicurezza."
L["rm.sod.warlock.fire.icyveins.Name"] = "Fuoco, Conflagrazione appena pronta (SoD, Icy Veins)"
L["rm.sod.warlock.fire.icyveins.Description"] = "La Distruzione della Season of Discovery di Icy Veins e Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Fuoco della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Immolazione sempre attiva, Conflagrazione e Dardo del Caos appena pronti (Dardo del Caos anche sotto il 35%), l'effetto benefico di Incenerimento, Fuoco dell'Anima con Decimazione sotto il 35%, Incenerimento come riempitivo; la maledizione dei danni solo in movimento, con Avventatezza in gruppo quando nessuno l'ha messa."
L["rm.sod.warlock.shadow.Name"] = "Ombra, Afflizione e Vilguardia (SoD)"
L["rm.sod.warlock.shadow.Description"] = "Build Afflizione e Vilguardia della Season of Discovery, e ogni Stregone della Season of Discovery a cui non si adatta nessun'altra rotazione integrata; costruita a partire da simulatore Fase 6, Wowhead e Icy Veins. Proc di Notte Fonda; Combustione dell'Ombra o Risucchio d'Anima per finire un bersaglio in gruppo; un bersaglio in punto di morte quando giochi da solo riceve Risucchio d'Anima, non DoT; incantesimi istantanei in movimento; Lago di Fuoco e Fuoco Infernale sui gruppi di nemici; una maledizione (Avventatezza in gruppo quando nessuno l'ha messa, altrimenti Agonia); Afflizione Instabile, Risucchio di Vita con Maestro dell'Incanalamento, Ombrofuoco (Immolazione prima di averlo), Corruzione, Tormento, Aspirazione della Vita (ciascuno rinnovato sotto i 6 secondi con Invocazione inciso); Risucchio d'Anima sotto il 20% con Aspirazione dell'Anima inciso; sostentamento da solo e la bacchetta; Dardo d'Ombra. Promemoria: Armatura Vile, il tuo famiglio (una Vilguardia una volta incisa), Conversione Vitale per un famiglio a corto di mana, Amplificazione Maledizione e i promemoria di sicurezza. L'assegnazione delle maledizioni e Raffica di Dardi d'Ombra sui gruppi di nemici restano a te."
L["rm.sod.warlock.shadow.simulator.Name"] = "Ombra, Risucchio d'Anima come riempitivo (SoD, simulatore)"
L["rm.sod.warlock.shadow.simulator.Description"] = "La lista Afflizione della Fase 6 di simulatore per una build Aspirazione dell'Anima, un'alternativa alla rotazione integrata consigliata Ombra della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Risucchio d'Anima è il riempitivo a qualsiasi livello di salute, e il passaggio successivo viene mostrato appena è dovuto, così puoi interrompere l'incanalamento per eseguirlo; qualsiasi altro incanalamento viene lasciato finire. Afflizione Instabile e Ombrofuoco rinnovati quando restano 7,5 secondi, Agonia e Corruzione quando ne restano 6, Risucchio di Vita con Maestro dell'Incanalamento, Tormento, Dardo d'Ombra solo con un proc di Trance d'Ombra, Aspirazione della Vita, Conversione Vitale sotto il 10% di mana. Stessi promemoria della rotazione integrata consigliata."
L["rm.sod.warlock.tank.Name"] = "Difensore (SoD, Metamorfosi)"
L["rm.sod.warlock.tank.Description"] = "Difensore della Season of Discovery, scelta una volta incisa Metamorfosi; costruita a partire da simulatore, Icy Veins, Wowhead e Warcraft Tavern. Fendente d'Ombra ogni volta che Risolutezza del Difensore manca o sta per finire, un proc di Fuoco dell'Anima!, Incenerimento per mantenere il suo effetto benefico del fuoco; contro tre o più nemici Fendente d'Ombra, Lago di Fuoco, Ombrofuoco e Fuoco Infernale. Poi una maledizione (Agonia, altrimenti Avventatezza quando nessuno l'ha messa), Ombrofuoco (Immolazione prima di inciderlo), Risucchio di Vita con Maestro dell'Incanalamento, Corruzione, Aspirazione della Vita, Conflagrazione per Ritorno di Fiamma, Fuoco dell'Anima con Decimazione sotto il 35%, e Dolore Ustionante come riempitivo per la minaccia. Promemoria: Metamorfosi, Armatura Vile, il tuo famiglio, Rogo Rovente, Grazia Demoniaca, Vendetta quando sei in difficoltà, Minaccioso quando il bersaglio attacca qualcun altro, Ululato Demoniaco sui gruppi di nemici, Amplificazione Maledizione, Conversione Vitale per un famiglio a corto di mana. Armatura Infernale resta a te."
L["rm.tbc.warlock.dps.icyveins.Name"] = "Tutti gli alberi (Icy Veins)"
L["rm.tbc.warlock.dps.icyveins.Description"] = "Ogni albero dei talenti dal livello 1 al 70. Maledizione, poi Afflizione Instabile, Immolazione, Corruzione e Sifone di Vita man mano che li apprendi, Dardo d'Ombra o Incenerimento; prima gli effetti di Calar della Notte e Contraccolpo; Seme della Corruzione, Fuoco Infernale e Furia dell'Ombra contro tre o più nemici. Da solo usa i risucchi quando sei ferito, Conversione Vitale, la bacchetta, e Risucchio d'Anima o un colpo di grazia su un bersaglio in punto di morte. Promemoria: Armatura Vile, Armatura Demoniaca o Pelle Demoniaca, il tuo demone, il sacrificio, Legame d'Anima, Amplifica Maledizione e Frantumazione d'Anima. Paure e altre maledizioni restano a te."
L["rm.tbc.warlock.dps.wowhead.Name"] = "Risucchio difensivo (Wowhead)"
L["rm.tbc.warlock.dps.wowhead.Description"] = "Stregone secondo le guide di Wowhead, un'alternativa alla rotazione integrata consigliata dello Stregone di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Da solo fa \"drain-tanking\": Risucchio di Vita è il riempitivo una volta attivi i tuoi danni periodici, e Immolazione e Sifone di Vita sono riservati ai mostri élite. In gruppo Immolazione va sempre applicata, dopo Corruzione e Sifone di Vita. Per il resto è uguale alla rotazione integrata consigliata."
